 void ContentRoadDetails(Node3D root,int cx,int cz,bool simulation){if(simulation)return;int z=cz*64+32;double x=game.World.RouteX(z)+(game.World.Tier(game.World.RouteX(z),z)<=2?12:17);if(x<cx*64||x>=(cx+1)*64||!game.World.Playable(x,z)||InEncounterLot(x,z)||InLivingLot(x,z))return;uint h=game.World.Hash(cx+41,cz-94);var at=Ground(x,z);Tube(root,at,at+Vector3.Up*2,.05f,Wood);string area=z> -300?"WOODLAND / NORTHWEST":z> -1200?"HIGHWAY / NORTHWEST":z> -1740?"SOUTH CITY / NORTHWEST":"RIVER CROSSING CLOSED";if((cz&1)==0){Box(root,at+new Vector3(0,1.7f,0),new(3,.65f,.12f),new(.24f,.32f,.26f));root.AddChild(new Label3D{Text=area,Position=at+new Vector3(0,1.7f,.08f),RotationDegrees=new(0,180,0),FontSize=19,PixelSize=.006f});}else{Box(root,at+new Vector3(1,.5f,0),new(.8f,1,.6f),Steel,true);Box(root,at+new Vector3(1,.9f,-.31f),new(.5f,.08f,.02f),Ink);for(int j=0;j<3;j++)Box(root,at+new Vector3(j*.5f,.08f,1),new(.35f,.16f,.45f),h%2==0?Wood:Steel);}}
